"""Real-browser feature checks; SwiftShader is not a hardware FPS benchmark."""
import os,json,io,wave,math,struct
from pathlib import Path
from playwright.sync_api import sync_playwright
from PIL import Image,ImageChops,ImageStat
os.environ.pop('DISPLAY',None)
ROOT=Path(__file__).resolve().parents[1];E=ROOT/'evidence';results=[]
def check(name,ok):
 results.append({'check':name,'pass':bool(ok)});print(('PASS ' if ok else 'FAIL ')+name,flush=True)
 (E/'studio-browser-results.json').write_text(json.dumps(results,indent=2))
 if not ok: raise AssertionError(name)
with sync_playwright() as pw:
 browser=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM_PATH') or ('/usr/bin/chromium' if Path('/usr/bin/chromium').exists() else None),headless=True,args=['--no-sandbox','--enable-unsafe-swiftshader','--use-angle=swiftshader','--disable-dev-shm-usage'])
 context=browser.new_context(viewport={'width':1160,'height':820},device_scale_factor=1,accept_downloads=True)
 page=context.new_page();page.set_default_timeout(30000);errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
 page.set_content((ROOT/'index.html').read_text(),wait_until='load');page.wait_for_function('window.bubbleUI&&bubbleUI.atlasReady===1');page.wait_for_timeout(300)
 check('Bootstrap Offcanvas is locally loaded',page.evaluate('typeof bootstrap.Offcanvas==="function"'))
 check('one canvas, two surfaces, one draw call',page.evaluate('document.querySelectorAll("canvas").length===1&&bubbleUI.getStats().surfaces===2&&bubbleUI.getStats().drawCalls===1'))
 check('61 controls and five sidebar size buttons',page.locator('[data-control]').count()==61 and page.locator('#settings-panel [data-size]').count()==5 and page.locator('header [data-size]').count()==0)
 check('page is pure black',page.evaluate('getComputedStyle(document.body).backgroundColor==="rgb(0, 0, 0)"'))
 point=page.evaluate('bubbleUI.inspect().find(p=>p.eligible&&p.mode==="poppable"&&p.x>220&&p.x<450&&p.y>240)')
 page.mouse.click(point['x'],point['y']);page.wait_for_function('bubbleUI.getStats().popped===1')
 taps=page.evaluate(f'bubbleUI.inspect()[{point["index"]}].taps');page.mouse.click(point['x'],point['y'])
 check('repeat tap adds impulse, not another pop',page.evaluate(f'bubbleUI.inspect()[{point["index"]}].taps>{taps}&&bubbleUI.getStats().popped===1'))
 page.wait_for_function(f'Math.abs(bubbleUI.inspect()[{point["index"]}].bounce)>.005');check('retap has nonzero bounce',True)
 page.locator('#settings-toggle').click();page.wait_for_function('document.querySelector("#settings-panel").classList.contains("show")')
 check('sidebar opens accessibly',page.locator('#settings-toggle').get_attribute('aria-expanded')=='true')
 check('panel keeps popped progress',page.evaluate('bubbleUI.getStats().popped===1'))
 check('no backdrop blocks sheet',page.locator('.offcanvas-backdrop').count()==0)
 page.locator('#control-search').fill('cut irregularity')
 check('search filters controls',page.locator('[data-control="edgeRoughness"]').is_visible() and not page.locator('[data-control="contrast"]').is_visible())
 page.locator('#control-search').fill('')
 def setting(key,value):
  page.evaluate('([key,value])=>{const n=document.getElementById("setting-"+key);if(n.type==="checkbox"){n.checked=value;n.dispatchEvent(new Event("change",{bubbles:true}));}else{n.value=String(value);n.dispatchEvent(new Event(n.tagName==="SELECT"?"change":"input",{bubbles:true}));}}',[key,value])
 def pixels():
  page.wait_for_timeout(300);return Image.open(io.BytesIO(page.screenshot())).convert('RGB').crop((60,155,650,640))
 def difference(a,b):return sum(ImageStat.Stat(ImageChops.difference(a,b)).mean)
 setting('motion',False);normal=pixels();setting('contrast',1.6);high=pixels()
 check('contrast changes rendered pixels',difference(normal,high)>8)
 check('grading preserves progress',page.evaluate('bubbleUI.getStats().popped===1'))
 setting('contrast',1.04);setting('blendMode',1);setting('backingLevel',.48);soft=pixels()
 check('Soft Light changes shader pixels',difference(normal,soft)>5)
 setting('blendMode',2);setting('backingLevel',0);dark=pixels()
 check('Darken over black is black',max(ImageStat.Stat(dark).mean)<1)
 setting('blendMode',0);setting('backingLevel',.24);setting('blackPoint',.12)
 check('black-point changes material',difference(normal,pixels())>3)
 setting('blackPoint',.012);setting('grain',.12)
 check('grain changes material pixels',difference(normal,pixels())>1)
 setting('grain',.008);setting('motion',True);setting('edgeRoughness',9);setting('cornerRadius',3)
 check('new cut boundaries keep cut bubbles flat',page.evaluate('bubbleUI.inspect().filter(p=>p.cut).every(p=>p.popped&&p.squish===1)'))
 check('cut changes preserve one draw call',page.evaluate('bubbleUI.getStats().drawCalls===1'))
 setting('exposure',.37);page.wait_for_timeout(500)
 check('blocked browser storage has an explicit fallback',page.locator('#preset-status').text_content().startswith('Storage unavailable'))
 with page.expect_download() as dl:page.locator('#preset-export').click()
 preset=json.loads(Path(dl.value.path()).read_text());check('JSON export contains versioned settings',preset['version']==3 and preset['settings']['exposure']==.37)
 imported={'version':3,'settings':{'contrast':1.23,'edgeRoughness':6.5,'bubbleSize':82,'blendMode':1,'backingLevel':.47}}
 page.locator('#preset-file').set_input_files({'name':'preset.json','mimeType':'application/json','buffer':json.dumps(imported).encode()});page.wait_for_function('bubbleUI.settings.contrast===1.23')
 check('JSON import updates material and size',page.evaluate('bubbleUI.settings.bubbleSize===82') and page.locator('[data-size="82"]').get_attribute('aria-pressed')=='true')
 page.locator('#preset-file').set_input_files({'name':'bad.json','mimeType':'application/json','buffer':b'{"version":9}'})
 page.wait_for_function('document.getElementById("preset-status").textContent.includes("version 3")')
 check('invalid preset rejected',page.evaluate('bubbleUI.settings.contrast===1.23'))
 page.locator('#inspect-crops').click();check('crop dialog opens',page.evaluate('document.getElementById("crop-dialog").open'))
 page.locator('[data-audit="crops"]').click();page.wait_for_function('document.getElementById("crop-image").complete&&document.getElementById("crop-image").naturalWidth>100')
 check('embedded source crop review loads',page.locator('[data-audit="crops"]').get_attribute('aria-pressed')=='true');page.locator('#crop-close').click()
 check('audio fallback is honestly identified',page.evaluate('bubbleUI.audio.sampleLabel==="Synthesized fallback"'))
 buf=io.BytesIO()
 with wave.open(buf,'wb') as f:
  f.setnchannels(1);f.setsampwidth(2);f.setframerate(22050);f.writeframes(b''.join(struct.pack('<h',int(10000*math.sin(2*math.pi*440*i/22050)*math.exp(-i/900))) for i in range(3308)))
 page.locator('#audio-files').set_input_files({'name':'test-pop.wav','mimeType':'audio/wav','buffer':buf.getvalue()});page.wait_for_function('bubbleUI.audio.sampleLabel==="1 imported sample"')
 check('imported WAV decodes and is selected',True)
 page.evaluate('document.getElementById("audio-test").click()');page.wait_for_timeout(180)
 check('audio sample playback leaves context running',page.evaluate('bubbleUI.audio.state==="running"'))
 page.locator('#audio-files').set_input_files({'name':'bad.wav','mimeType':'audio/wav','buffer':b'not audio'});page.wait_for_function('document.getElementById("audio-source").textContent.toLowerCase().includes("error")')
 check('invalid audio preserves previous good sample',page.evaluate('bubbleUI.audio.sampleLabel==="1 imported sample"'))
 page.evaluate('document.getElementById("settings-defaults").click()');page.locator('#settings-close').click();page.wait_for_timeout(350)
 check('sidebar collapses to trigger',not page.locator('#settings-panel').is_visible() and page.locator('#settings-toggle').is_visible())
 check('Defaults returns the sheet to M',page.evaluate('bubbleUI.settings.bubbleSize===64'));page.wait_for_timeout(250)
 h=page.locator('[data-corner="0"]').bounding_box();hx=h['x']+h['width']/2;hy=h['y']+h['height']/2
 page.mouse.move(hx,hy);page.mouse.down();page.mouse.move(hx+85,hy+65,steps=8);page.wait_for_function('bubbleUI.inspectMotion().corners[0]>10')
 check('corner drag bends sheet in XY and height',page.evaluate('bubbleUI.inspectMotion().corners[0]>10&&bubbleUI.inspectMotion().corners[2]>10'))
 mapping=page.evaluate('(()=>{const p=bubbleUI.inspect().find(p=>p.eligible&&p.mode==="poppable"&&p.row===2&&p.col===2);const q=bubbleUI.project(p.x,p.y);return {a:p.index,b:bubbleUI.hitTest(q.x,q.y),dx:q.x-p.x};})()')
 check('hit testing follows deformed coordinates',mapping['a']==mapping['b'] and abs(mapping['dx'])>1)
 page.screenshot(animations='disabled',path=str(E/'studio-corner-drag.png'));page.mouse.up()
 check('corner release clears targets',page.evaluate('bubbleUI.inspectMotion().targets.every(x=>x===0)'))
 page.wait_for_function('Math.max(...bubbleUI.inspectMotion().corners.map(Math.abs))<.1',timeout=45000);check('released sheet springs back',True)
 page.locator('#settings-toggle').click();page.wait_for_timeout(300);page.screenshot(animations='disabled',path=str(E/'studio-controls.png'));page.locator('#settings-close').click();page.wait_for_timeout(250);page.screenshot(animations='disabled',path=str(E/'studio-desktop.png'))
 page.evaluate('bubbleUI.setSettings({exposure:.42,blendMode:5});');page.wait_for_timeout(500);check('imperative settings updates remain functional',page.evaluate('bubbleUI.settings.exposure===.42&&bubbleUI.settings.blendMode===5'))
 check('no JavaScript runtime errors',not errors)
 mobile=browser.new_context(viewport={'width':390,'height':844},device_scale_factor=1,is_mobile=True,has_touch=True);mp=mobile.new_page();mp.set_content((ROOT/'index.html').read_text(),wait_until='load');mp.wait_for_function('window.bubbleUI&&bubbleUI.atlasReady===1');mp.locator('#settings-toggle').tap();mp.wait_for_timeout(350)
 check('mobile panel fits without overflow',mp.locator('#settings-panel').bounding_box()['width']<=390 and mp.evaluate('document.documentElement.scrollWidth===innerWidth'))
 mp.screenshot(animations='disabled',path=str(E/'studio-mobile-panel.png'));mp.locator('#settings-close').tap();mp.wait_for_timeout(250)
 check('mobile counter does not overlap tuning trigger',mp.evaluate('document.querySelector(".counter").getBoundingClientRect().right<document.getElementById("settings-toggle").getBoundingClientRect().left'))
 mp.screenshot(animations='disabled',path=str(E/'studio-mobile.png'));browser.close()
print(json.dumps({'passed':sum(x['pass'] for x in results),'total':len(results)},indent=2))
